import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.Ch_0qWu9.js";const k=JSON.parse('{"title":"Solver 协议","description":"","frontmatter":{"sourcePath":"docs/solver-protocols.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/docs/solver-protocols.zh-CN.md","alternateUrl":"/TCSExam/docs/solver-protocols/","alternateAnchors":{"solver-协议":"solver-protocols","反馈与默认设置":"feedback-and-defaults","选择并准备协议":"select-and-prepare-a-protocol","报告所选协议":"report-the-selected-protocol","solver-protocols":"solver-protocols","feedback-and-defaults":"feedback-and-defaults","select-and-prepare-a-protocol":"select-and-prepare-a-protocol","report-the-selected-protocol":"report-the-selected-protocol"}},"headers":[],"relativePath":"zh/solver-protocols/index.md","filePath":"zh/solver-protocols/index.md"}'),l={name:"zh/solver-protocols/index.md"};function i(r,e,d,n,p,h){return s(),t("div",null,[...e[0]||(e[0]=[o(`<p><a id="solver-protocols"></a></p><h1 id="solver-协议" tabindex="-1">Solver 协议 <a class="header-anchor" href="#solver-协议" aria-label="Permalink to &quot;Solver 协议&quot;">​</a></h1><p>本指南定义 Solver 开发期间的反馈方式和协议选择方法。 面向选择评测协议或准备相关依赖的用户。</p><p><a id="feedback-and-defaults"></a></p><h2 id="反馈与默认设置" tabindex="-1">反馈与默认设置 <a class="header-anchor" href="#反馈与默认设置" aria-label="Permalink to &quot;反馈与默认设置&quot;">​</a></h2><p>Full 包含 100 道题；Lite 从 Full 的各类题目中选取 20 道。在任一套件中， <code>--solver-protocol online|offline</code> 用于选择 Solver 开发期间的反馈协议。 两种选择下，定理、构造和开放猜想题均共用相同目录。Full 默认使用 <code>online</code>； Lite 默认使用 <code>offline</code>。两个套件都允许显式覆盖默认值。</p><p>读法说明：每行描述一套完整的开发与终判协议。</p><table tabindex="0"><thead><tr><th>协议</th><th>十二小时开发期间</th><th>开发结束后</th></tr></thead><tbody><tr><td><code>online</code></td><td><code>submit.sh</code> 可以请求判分并返回反馈</td><td>在隐藏实例上评判最终提交</td></tr><tr><td><code>offline</code></td><td>在公开实例上运行本地自测</td><td>在隐藏实例上评判最终提交</td></tr></tbody></table><p>Offline 在开发期间不提供隐藏判分反馈。两种协议使用相同的最终题目检查器和计分规则。</p><p>互联网访问是独立的题目设置：允许的网络使用范围以题目配置和说明为准。</p><p><a id="select-and-prepare-a-protocol"></a></p><h2 id="选择并准备协议" tabindex="-1">选择并准备协议 <a class="header-anchor" href="#选择并准备协议" aria-label="Permalink to &quot;选择并准备协议&quot;">​</a></h2><p>全部三十道 Solver 题目均提供 online 和 offline 题包。 <a href="https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/suites/tasks.json" target="_blank" rel="noreferrer">题目注册表</a> 将题目映射到对应的 Harbor 目录。 套件选择和协议选择会解析这些目录，不改变题目内容。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> online</span></span></code></pre></div><p>用 <a href="/TCSExam/docs/zh/resources/"><code>tcsexam build</code></a> 准备选定镜像，然后以相同选项运行 <code>tcsexam doctor</code>。缺少依赖时，<code>run</code> 会在发出任何模型请求之前停止；缺少某个变体会报错。</p><p>Online 还需要用户自行运营判分后端。题包提供客户端和判分代码； <a href="/TCSExam/docs/zh/solver-backend/">TCSEXAM 接口</a> 定义身份认证、会话、尝试标识和结果归档。</p><p>Offline 在开发结束后使用独立的判分适配器。适配器根据可用 CPU 和内存选择并发数， 资源不足时可退回串行执行，同时保留逐实例限额。共享时间池题目仍使用同一个时间池。 模型环境与隐藏数据和 Docker 控制器隔离。适配器行为见 <a href="/TCSExam/docs/zh/offline-adapters/">离线适配器</a>。</p><p><a id="report-the-selected-protocol"></a></p><h2 id="报告所选协议" tabindex="-1">报告所选协议 <a class="header-anchor" href="#报告所选协议" aria-label="Permalink to &quot;报告所选协议&quot;">​</a></h2><p>online 和 offline 结果应分别形成独立系列，即使它们选择了相同题目。 记录实际使用的协议，以及套件、源码提交、模型和 agent 版本、计分依据及采用的尝试次数。 参见<a href="/TCSExam/docs/zh/citation/#citing-results">报告字段</a>。</p>`,20)])])}const f=a(l,[["render",i]]);export{k as __pageData,f as default};
